var animating = false;
var submitPhase2 = 0;
var $login = document.querySelector(".login");
var $status = document.querySelector("#status");
var $loginSubmit = document.querySelector(".login-submit");
var $logoutSubmit = document.querySelector(".logout-submit");
var loggedIn = false;
var intervalStatus = false;
var currentLoginUsername = "";
var errorNoticeTimer = null;

function showErrorNotice(message) {
    var error = document.getElementById("error");

    if (error === null) {
        return;
    }

    clearTimeout(errorNoticeTimer);
    error.innerText = message;
    error.classList.add("show");

    errorNoticeTimer = setTimeout(function () {
        error.classList.remove("show");
    }, 5000);
}

function clearErrorNotice() {
    var error = document.getElementById("error");

    if (error === null) {
        return;
    }

    clearTimeout(errorNoticeTimer);
    error.classList.remove("show");
    error.innerText = "";
}


function padDateNumber(value) {
    value = String(value).replace(/\D/g, "");
    return value.length === 1 ? "0" + value : value;
}

function setHeaderDates() {
    var gregorianTarget = document.getElementById("gregorianDate");
    var hijriTarget = document.getElementById("hijriDate");

    if (gregorianTarget === null || hijriTarget === null) {
        return;
    }

    var now = new Date();
    var gregorianDay = padDateNumber(now.getDate());
    var gregorianMonth = padDateNumber(now.getMonth() + 1);
    var gregorianYear = now.getFullYear();

    gregorianTarget.innerHTML = "<span class='date-label'>ميلادي:</span> <b>" + gregorianYear + "/" + gregorianMonth + "/" + gregorianDay + "</b>";

    try {
        var hijriParts = new Intl.DateTimeFormat("en-TN-u-ca-islamic", {
            day: "2-digit",
            month: "2-digit",
            year: "numeric"
        }).formatToParts(now);
        var hijriDay = "";
        var hijriMonth = "";
        var hijriYear = "";

        for (var i = 0; i < hijriParts.length; i++) {
            if (hijriParts[i].type === "day") {
                hijriDay = padDateNumber(hijriParts[i].value);
            } else if (hijriParts[i].type === "month") {
                hijriMonth = padDateNumber(hijriParts[i].value);
            } else if (hijriParts[i].type === "year") {
                hijriYear = hijriParts[i].value.replace(/\D/g, "");
            }
        }

        hijriTarget.innerHTML = "<span class='date-label'>هجري:</span> <b>" + hijriYear + "/" + hijriMonth + "/" + hijriDay + "</b>";
    } catch (error) {
        hijriTarget.innerHTML = "";
    }
}





function getCurrentLoginUsername() {
    if (currentLoginUsername !== "") {
        return currentLoginUsername;
    }

    if (document.login && document.login.username && document.login.username.value !== "") {
        return document.login.username.value;
    }

    if (typeof getLoginCardCookie === "function") {
        var cardCookie = getLoginCardCookie();
        if (cardCookie.username !== "") {
            return cardCookie.username;
        }
    }

    return "";
}

function setStatusUsername(username) {
    var target = document.getElementById("username");

    if (target !== null && username !== "") {
        target.innerText = username;
    }
}

function onLoginSubmitted() {
    if (document.login.username.value.length >= 1) {
        currentLoginUsername = document.login.username.value;
        setStatusUsername(currentLoginUsername);
        clearErrorNotice();
        $loginSubmit.classList.add("processing");
        userLogin();
        return false;
    }

    showErrorNotice("يجب ادخال قيمة صحيحة!");
}

function showParentElement(button, target) {
    button.classList.add("success");

    setTimeout(function () {
        target.style.display = "block";
        getComputedStyle(target).top;
        target.classList.add("active");
    }, submitPhase2 - 70);

    setTimeout(function () {
        hideLoginPage();
        animating = false;
        button.classList.remove("success", "processing");
    }, submitPhase2);
}

function hideLoginPage() {
    $login.style.display = "none";
    $login.classList.add("inactive");
}

function showLoginPage() {
    $login.style.display = "block";
    getComputedStyle($login).top;
    $login.classList.remove("inactive");
}

function initHotspotEvents(button, target) {
    var backs = target.querySelectorAll(".app-logout");

    button.addEventListener("click", function () {
        if (!animating) {
            animating = true;
            this.classList.add("processing");
            showParentElement(this, target);
        }
    });

    for (var i in backs) {
        var back = backs[i];

        if (typeof back === "object") {
            back.addEventListener("click", function () {
                if (!animating) {
                    animating = true;
                    var clickedBack = this;

                    setTimeout(function () {
                        target.classList.remove("active");
                        showLoginPage();
                    }, submitPhase2 + 120);

                    setTimeout(function () {
                        target.style.display = "none";
                        animating = false;
                        clickedBack.classList.remove("processing");
                    }, submitPhase2);
                }
            });
        }
    }
}

function toArabicTime(value) {
    var time = value;
    var days = "";
    var hours = "";
    var minutes = "";
    var seconds = "";

    if (value === "") {
        return "";
    }

    if (value.indexOf("d") >= 0) {
        time = value.split("d");
        days = time[0] !== "" ? time[0] + " يوم " : "";
        time = time[1];
    }

    if (value.indexOf("h") >= 0) {
        time = time.split("h");
        hours = time[0] !== "" ? time[0] + " ساعة " : "";
        time = time[1];
    }

    if (value.indexOf("m") >= 0) {
        time = time.split("m");
        minutes = time[0] !== "" ? time[0] + " دقيقة " : "";
        time = time[1];
    }

    if (value.indexOf("s") >= 0) {
        value = time.split("s");
        seconds = value[0] !== "" ? value[0] + " ثانية " : "";
    }

    return days + hours + minutes + seconds;
}

function toArabicBytes(value) {
    if (value < 1024) {
        return value + " بايت ";
    }

    if (value < 1048576) {
        return Math.round(value / 1024) + " كيلوبايت ";
    }

    if (value < 1073741824) {
        return Math.round(value / 1048576) + " ميجابايت ";
    }

    return (value / 1073741824).toFixed(2) + " جيجابايت ";
}

function toArabicError(error) {
    var errors = {
        "user&not found": "لقد ادخلت الكرت بطريقة غير صحيحة، الرجاء المحاولة مرة اخرى",
        "simultaneous session limit reached|no more sessions are allowed": "المعذرة ، هذا الكرت مستخدم حالياً في جهاز آخر",
        "invalid password": "تاكد من كتابة كلمة المرور بشكل صحيح",
        "uptime limit reached|No more online time|uptime limit": "عذراً لقد انتهى الوقت المتاح لك",
        "traffic limit|transfer limit reached": "لقد انتهى رصيد هذا الكرت",
        "invalid username or password|not found": "لقد ادخلت اسم المستخدم بطريقة غير صحيحة، الرجاء المحاولة مرة اخرى",
        "no valid profile found": "لقد انتهت صلاحية هذا الكرت",
        "invalid Calling-Station-Id": "هذا الكرت مقترن بجهاز آخر!",
        "server&is&not&responding": "يرجى الانتظار، يتم الآن اعادة تشغيل الشبكة، هذه العملية قد تستغرق بعض الوقت",
        "web&browser&did&not&send": "يرجى محاولة ادخال الكرت مرة اخرى"
    };
    var message = "حصل خطأ: " + error;

    for (var key in errors) {
        var text = errors[key];

        if (key.indexOf("&") > -1) {
            var parts = key.split("&");
            var matched = true;

            for (var i = 0; i < parts.length; i++) {
                if (error.indexOf(parts[i]) === -1) {
                    matched = false;
                    break;
                }
            }

            if (matched) {
                message = text;
                break;
            }
        } else if (key.indexOf("|") > -1) {
            var options = key.split("|");

            for (var j = 0; j < options.length; j++) {
                if (error.indexOf(options[j]) > -1) {
                    message = text;
                    break;
                }
            }
        } else if (error.indexOf(key) > -1) {
            message = text;
            break;
        }
    }

    return message;
}

function onLoginStart(response) {
    cookieLogin();
}

function onLoginError(response) {
    currentLoginUsername = "";
    document.login.reset();
    $loginSubmit.classList.remove("success", "processing");
    animating = false;
    showErrorNotice(toArabicError(response.error));

    var blocker = document.querySelector("script[enable-hot-blocker]");

    if (blocker !== null) {
        var counter = incrementCounter(blocker);
        checkFailsCount(blocker, counter);
    }

    clearCookies();
}

function onLoggedIn(response) {
    resetCounter();
    loggedIn = true;
    setStatusUsername(getCurrentLoginUsername());
    showParentElement($loginSubmit, document.getElementById("status"));
    startStatusQuery();
}

function onLoggedOut(response) {
    loggedIn = false;
    currentLoginUsername = "";
}

function onStatusQuery(response) {
    if (response.logged_in) {
        if (response.username && response.username !== "") {
            currentLoginUsername = response.username;
        }

        for (var key in response) {
            var value = response[key];

            if (typeof value === "string" && key !== "logged_in") {
                var target = document.getElementById(key);

                if (target !== null) {
                    if (value === "") {
                        value = document.querySelector("[" + key + "]");
                    } else if (key === "username") {
                        target.innerText = value;
                    } else if (key.indexOf("bytes") > -1) {
                        target.innerText = toArabicBytes(value);
                    } else if (key.indexOf("time") > -1) {
                        target.innerText = toArabicTime(value);
                    } else {
                        target.innerText = value;
                    }
                }
            }
        }

        setStatusUsername(getCurrentLoginUsername());
    } else {
        loggedIn = false;
    }
}

function getRequest(url) {
    var request = new XMLHttpRequest();

    request.open("GET", url, true);
    request.onreadystatechange = function () {
        if (this.readyState === 4 && this.status >= 200 && this.status < 400) {
            var response = JSON.parse(this.responseText);
            window[response.action](response);
        }
    };
    request.send();
    request = null;
}

function userLogin() {
    currentLoginUsername = document.login.username.value;
    setStatusUsername(currentLoginUsername);
    getRequest("/login?username=" + currentLoginUsername + "&var=callBack");
}

function userLogout(eraseCookie) {
    getRequest(eraseCookie ? "/logout?erase-cookie=yes&var=callBack" : "/logout?var=callBack");
}

var $statusflag = true;

function startStatusQuery() {
    if ($statusflag && !intervalStatus && loggedIn) {
        intervalStatus = true;
        getRequest("/status?var=callBack");

        var statusInterval = setInterval(function () {
            if (loggedIn) {
                getRequest("status?var=callBack");
            } else {
                intervalStatus = false;
                clearInterval(statusInterval);
            }
        }, 1000);
    }
}

function Ulogin(username, password, domain) {
    if (domain !== "") {
        domain = "&domain=" + domain;
    }

    getRequest("/login?username=" + username + "&password=" + password + "&var=callBack" + domain);
}

function openStatusCustomerService() {
    var servicePage = document.getElementById("status-customer-service");

    if (servicePage === null || $status === null) {
        return;
    }

    $status.classList.remove("active");
    $status.style.display = "none";
    servicePage.style.display = "block";
    getComputedStyle(servicePage).top;
    servicePage.classList.add("active");
}

function closeStatusCustomerService() {
    var servicePage = document.getElementById("status-customer-service");

    if (servicePage !== null) {
        servicePage.classList.remove("active");
        servicePage.style.display = "none";
    }

    if (loggedIn && $status !== null) {
        $status.style.display = "block";
        getComputedStyle($status).top;
        $status.classList.add("active");
    } else {
        showLoginPage();
    }
}

if ($loginSubmit !== null) {
    $loginSubmit.addEventListener("click", function () {
        onLoginSubmitted();
    });
}

if ($logoutSubmit !== null) {
    $logoutSubmit.addEventListener("click", function () {
        userLogout();
        currentLoginUsername = "";
        $status.style.display = "none";
        $status.classList.remove("active");
        showLoginPage();
    });
}

var statusCustomerServiceButton = document.getElementById("statusCustomerServiceButton");
var statusCustomerServiceBack = document.getElementById("statusCustomerServiceBack");

if (statusCustomerServiceButton !== null) {
    statusCustomerServiceButton.addEventListener("click", openStatusCustomerService);
}

if (statusCustomerServiceBack !== null) {
    statusCustomerServiceBack.addEventListener("click", closeStatusCustomerService);
}



function openAdLightbox(imgSrc) {
    var overlay = document.getElementById("adLightboxOverlay");
    var targetImg = document.getElementById("adLightboxImg");

    if (overlay === null || targetImg === null) {
        return;
    }

    targetImg.src = imgSrc;
    overlay.classList.add("active");
    overlay.setAttribute("aria-hidden", "false");
}

function closeAdLightbox() {
    var overlay = document.getElementById("adLightboxOverlay");

    if (overlay !== null) {
        overlay.classList.remove("active");
        overlay.setAttribute("aria-hidden", "true");
    }
}

function initDynamicAdsTrack() {
    var container = document.getElementById("adsMarqueeContainer");
    var track = document.getElementById("adsTrack");
    var fallback = document.getElementById("adsFallbackBanner");

    if (container === null || track === null) {
        return;
    }

    var links = track.querySelectorAll("a");
    if (links.length === 0) {
        track.style.display = "none";
        if (fallback !== null) fallback.style.display = "block";
        return;
    }

    var validLinks = [];
    var checkedCount = 0;
    var totalCount = links.length;

    for (var i = 0; i < totalCount; i++) {
        (function (link) {
            var img = link.querySelector("img");
            if (img === null) {
                checkedCount++;
                link.style.display = "none";
                if (checkedCount === totalCount) finalizeTrack();
                return;
            }

            var testImg = new Image();
            testImg.onload = function () {
                validLinks.push(link);
                checkedCount++;
                if (checkedCount === totalCount) finalizeTrack();
            };
            testImg.onerror = function () {
                link.style.display = "none";
                checkedCount++;
                if (checkedCount === totalCount) finalizeTrack();
            };
            testImg.src = img.src;
        })(links[i]);
    }

    function finalizeTrack() {
        if (validLinks.length === 0) {
            track.style.display = "none";
            if (fallback !== null) {
                fallback.style.display = "block";
            }
        } else {
            if (fallback !== null) {
                fallback.style.display = "none";
            }
            track.style.display = "flex";

            if (validLinks.length < 4) {
                var contentHtml = track.innerHTML;
                track.innerHTML = contentHtml + contentHtml + contentHtml;
            }

            var activeLinks = track.querySelectorAll("a");
            for (var j = 0; j < activeLinks.length; j++) {
                activeLinks[j].addEventListener("click", function (e) {
                    e.preventDefault();
                    var clickedImg = this.querySelector("img");
                    if (clickedImg !== null) {
                        openAdLightbox(clickedImg.src);
                    }
                });
            }
        }
    }
}



var adLightboxCloseBtn = document.getElementById("adLightboxClose");
var adLightboxOverlayEl = document.getElementById("adLightboxOverlay");

if (adLightboxCloseBtn !== null) {
    adLightboxCloseBtn.addEventListener("click", closeAdLightbox);
}

if (adLightboxOverlayEl !== null) {
    adLightboxOverlayEl.addEventListener("click", function (e) {
        if (e.target === adLightboxOverlayEl) {
            closeAdLightbox();
        }
    });
}

document.addEventListener("DOMContentLoaded", function () {
    setHeaderDates();
    initDynamicAdsTrack();
    var buttons = document.querySelectorAll("button[parent-id]");

    for (var i in buttons) {
        var button = buttons[i];

        if (typeof button === "object") {
            var parentId = button.getAttribute("parent-id");
            var target = document.getElementById(parentId);

            if (target === null) {
                return;
            }

            initHotspotEvents(button, target);
        }
    }

    getRequest("/login?var=callBack");
}, false);
